ass="card"><h2 class="text-xl font-bold">Application Answers</h2><p class="mt-2 text-sm text-slate-500">Review relevance, practicality, and completeness. Do not score essay length or grammar. Indoor, outdoor, and combined arrangements are evaluated by their safety measures.</p><div class="mt-5 space-y-4"><?php foreach ($application['assessment_rows'] as $row): ?><article class="rounded-xl border border-slate-200 p-4"><div class="flex items-start justify-between gap-3"><h3 class="font-semibold text-slate-900"><?= esc($row['label']) ?></h3><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold text-slate-700"><?= esc($row['rating']) ?>/4 · <?= esc(number_format((float) $row['earned_points'], 2)) ?> pts</span></div><?php if (! empty($row['indicators'])): ?><details class="mt-3 text-xs text-slate-600"><summary class="cursor-pointer font-semibold text-rescue-700">Evaluation indicators</summary><ul class="mt-2 list-disc space-y-1 pl-5"><?php foreach ($row['indicators'] as $indicator): ?><li><?= esc($indicator) ?></li><?php endforeach ?></ul></details><?php endif ?><p class="mt-3 whitespace-pre-line text-sm leading-6 text-slate-700"><?= esc($row['response']) ?></p></article><?php endforeach; ?></div></div></section><aside class="space-y-6"><div class="card"><details><summary class="cursor-pointer text-lg font-bold text-slate-900">Documents</summary><div class="mt-4 space-y-2"><?php foreach ($documents as $label => $field): ?><?php if (! empty($application[$field])): ?><button type="button" @click="documentUrl = '<?= esc(base_url($application[$field]), 'js') ?>'; documentLabel = '<?= esc($label, 'js') ?>'" class="flex w-full items-center gap-2 rounded-lg border border-slate-200 p-3 text-left text-sm font-semibold hover:border-rescue-300 hover:bg-rescue-50"><i data-lucide="file-text" class="h-4 w-4 text-rescue-600"></i><?= esc($label) ?><i data-lucide="maximize-2" class="ml-auto h-4 w-4 text-slate-400"></i></button><?php endif; ?><?php endforeach; ?></div></details></div><div class="card"><h2 class="text-lg font-bold">Decision</h2><div class="mt-4 space-y-3"><?php foreach ($application['requested_cats'] as $cat): ?><div class="rounded-xl border border-slate-200 p-3"><p class="font-bold"><?= esc($cat['name']) ?></p><form method="post" action="<?= site_url('admin/applications/' . $application['id'] . '/cats/' . $cat['id']) ?>" class="mt-3 flex gap-2"><?= csrf_field() ?><select name="status" class="field text-sm"><?php foreach (['Under Review', 'Approved', 'Rejected'] as $status): ?><option <?= $cat['status'] === $status ? 'selected' : '' ?>><?= $status ?></option><?php endforeach; ?></select><button class="btn btn-primary">Save</button></form></div><?php endforeach; ?></div></div></aside></div><div x-cloak x-show="documentUrl" class="fixed inset-0 z-[200] bg-black/90 p-4" @keydown.escape.window="documentUrl = ''"><button type="button" @click="documentUrl = ''" class="absolute right-5 top-5 rounded-lg bg-white px-4 py-2 text-sm font-bold text-slate-800">Close</button><div class="flex h-full items-center justify-center"><img :src="documentUrl" :alt="documentLabel" class="max-h-full max-w-full object-contain"></div></div></div>
